/**
 * Codex adapter — drives OpenAI Codex through its official `codex app-server`
 * JSON-RPC protocol (the same protocol the Codex VS Code extension and desktop
 * app use). One app-server child serves every Kraki session; each Kraki
 * session maps to one Codex *thread*.
 *
 * Protocol reference (generated by the binary, pin-tested on codex-cli
 * 0.157.x):  codex app-server generate-ts --experimental --out <dir>
 *
 * Mapping summary
 *   Kraki session       ⇄ Codex thread   (thread/start · thread/resume · thread/fork)
 *   sendMessage         → turn/start     (steer → turn/steer)
 *   abortSession        → turn/interrupt
 *   agent prose         ← item/agentMessage/delta + item/completed(agentMessage)
 *   tool cards          ← item/started / item/completed (commandExecution,
 *                          fileChange, mcpToolCall, webSearch, imageView)
 *   permission cards    ← server requests item/commandExecution/requestApproval,
 *                          item/fileChange/requestApproval, item/permissions/requestApproval
 *   ask_user / show_image / kraki_get_mode
 *                       ← client-hosted dynamic tools (item/tool/call)
 *   turn boundary       ← turn/completed (completed | interrupted | failed)
 *
 * Permission model: every thread runs with `approvalPolicy: "untrusted"` (the
 * user's own sandbox setting is left untouched) so Codex asks the CLIENT before any
 * non-trivially-safe command or file change, and the ADAPTER applies Kraki's
 * four-mode policy (same as the Pi/Copilot adapters) — auto-approving silently
 * or raising a Kraki card. Kraki's mode is the single source of truth, and the
 * tentacle self-management guard sees every gated command in every mode.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Attachment, ModelDetail, ReasoningEffort, SessionUsage } from '@kraki/protocol';
import { AgentAdapter, type CreateSessionConfig, type PermissionDecision, type QuestionAnswer, type QuestionResponseResult, type PermissionResponseResult, type SendMessageOptions, type SessionInfo } from './base.js';
import { CodexRpcProcess, type RpcNotification } from './codex-rpc.js';
import { getConfigDir } from '../config.js';
import { showImageTool } from '../mcp/tools/show-image.js';
import { TurnTracker } from './turn-tracker.js';
import { KRAKI_MODES_PROMPT, modeChangeSignal } from './permission-policy.js';
import { TITLE_SYSTEM_PROMPT, buildTitlePrompt, cleanTitle, type TitleContext } from './title.js';
import { tmpdir } from 'node:os';
import { handleNotification } from './codex-notifications.js';
import { handleServerRequest, emitNativeQuestion } from './codex-requests.js';
import { str } from './codex-items.js';
import { logger, type Mode, DEFAULT_MODE, KRAKI_EFFORTS, mapCodexModels, makeId, errMessage, type PendingPermission, type QueuedInput, type CodexSession, type SessionSidecar, type CodexAdapterOptions, type CodexChildThread } from './codex-session.js';
export { unwrapShellCommand } from './codex-items.js';
export { codexShouldAutoApprove, mapCodexModels, type CodexAdapterOptions } from './codex-session.js';

// ── Adapter ───────────────────────────────────────────────

export class CodexAdapter extends AgentAdapter {
  rpc: CodexRpcProcess | null = null;
  sessions = new Map<string, CodexSession>();
  private threadToSession = new Map<string, string>();
  /** Subagent threads spawned (directly or nested) by a session's thread →
   * owning Kraki session. Only server requests (approvals, questions, Kraki
   * tools) and their withdrawals are routed through it; a subagent's own
   * messages and turn lifecycle never drive the parent session. */
  childThreads = new Map<string, CodexChildThread>();
  private models: ModelDetail[] = [];
  /** Ephemeral title threads awaiting their final agent message. */
  titleThreads = new Map<string, { text: string; done: (text: string | null) => void }>();
  private stopping = false;
  readonly opts: CodexAdapterOptions;

  static readonly DEVELOPER_INSTRUCTIONS = [
    'You are running inside Kraki, a remote-control harness. A human operator is',
    'monitoring and controlling this session from another device through an',
    'encrypted relay. Your commands and file changes are routed through Kraki\'s',
    'permission system, which approves, denies, or prompts the operator',
    'depending on the current mode.',
    '',
    KRAKI_MODES_PROMPT,
    'Call `kraki_get_mode` to check the live mode before irreversible or',
    'destructive actions.',
    '',
    'Kraki tools:',
    '- `ask_user`: ask the operator a question and block until they answer. Use it',
    '  whenever you need a decision or missing information; provide `choices` for',
    '  multiple choice. The return value is their literal answer.',
    '- `show_image`: display a local image (absolute path) in the operator\'s chat.',
    '  Only use it when they cannot already see the image and would learn',
    '  something new (a chart or diagram you generated, a screenshot of your own',
    '  machine). For images you only need to inspect, view them yourself instead.',
    '',
    'Communicate by writing ordinary prose — it is shown to the operator directly.',
    'End each turn with a short, self-contained final answer.',
  ].join('\n');

  constructor(options: CodexAdapterOptions) {
    super();
    this.opts = options;
  }

  // ── Storage ──────────────────────────────────────────

  private storeDir(sessionId: string): string {
    return join(this.opts.sessionsDir ?? join(getConfigDir(), 'sessions'), sessionId);
  }

  private sidecarPath(sessionId: string): string {
    return join(this.storeDir(sessionId), '.codex-adapter.json');
  }

  private loadSidecar(sessionId: string): SessionSidecar | null {
    const p = this.sidecarPath(sessionId);
    if (!existsSync(p)) return null;
    try { return JSON.parse(readFileSync(p, 'utf8')) as SessionSidecar; } catch { return null; }
  }

  private persist(s: CodexSession): void {
    try {
      mkdirSync(this.storeDir(s.sessionId), { recursive: true });
      const data: SessionSidecar = { threadId: s.threadId, cwd: s.cwd, model: s.model, effort: s.effort };
      writeFileSync(this.sidecarPath(s.sessionId), JSON.stringify(data), 'utf8');
    } catch (err) {
      logger.debug({ err: errMessage(err) }, 'codex persist failed');
    }
  }

  // ── Lifecycle ────────────────────────────────────────

  async start(): Promise<void> {
    this.stopping = false;
    await this.spawnServer();

    const account = await this.rpc!.request<{ account?: unknown; requiresOpenaiAuth?: boolean }>('account/read', {})
      .catch(() => null);
    if (account && account.account == null && account.requiresOpenaiAuth === true) {
      await this.rpc!.stop();
      this.rpc = null;
      throw new Error('Codex is not logged in. Run `codex login` (or set OPENAI_API_KEY) and restart Kraki.');
    }

    try {
      const res = await this.rpc!.request<{ data?: unknown }>('model/list', {});
      this.models = mapCodexModels(res?.data);
    } catch (err) {
      logger.warn({ err: errMessage(err) }, 'codex model/list failed');
    }
    logger.info({ models: this.models.map((m) => m.id) }, 'Codex adapter started');
  }

  private async spawnServer(): Promise<void> {
    const args = [...(this.opts.cliArgs ?? []), 'app-server'];
    const rpc = new CodexRpcProcess({
      command: this.opts.cliPath,
      args,
      env: this.opts.env ?? process.env,
      requestTimeoutMs: this.opts.requestTimeoutMs ?? 60_000,
    });
    rpc.onNotification = (n) => {
      try { handleNotification(this, n); } catch (err) {
        logger.error({ err: errMessage(err), method: n.method }, 'codex notification handler failed');
      }
    };
    rpc.onServerRequest = (r) => {
      handleServerRequest(this, r).catch((err) => {
        logger.error({ err: errMessage(err), method: r.method }, 'codex server request handler failed');
        rpc.respondError(r.id, errMessage(err));
      });
    };
    rpc.onExit = (info) => this.handleServerExit(rpc, info);
    rpc.start();
    this.rpc = rpc;
    await rpc.request('initialize', {
      clientInfo: { name: 'kraki', title: 'Kraki', version: '1' },
      // Required for client-hosted dynamic tools (ask_user / show_image).
      capabilities: { experimentalApi: true },
    }, 30_000);
    rpc.notify('initialized');
  }

  private async ensureServer(): Promise<CodexRpcProcess> {
    if (this.rpc?.alive) return this.rpc;
    if (this.stopping) throw new Error('Codex adapter is stopping');
    logger.warn('codex app-server not running — respawning');
    await this.spawnServer();
    return this.rpc!;
  }

  private handleServerExit(rpc: CodexRpcProcess, info: { code: number | null; signal: NodeJS.Signals | null; stderrTail: string }): void {
    if (this.rpc !== rpc) return;
    this.rpc = null;
    if (this.stopping) return;
    logger.warn({ code: info.code, signal: info.signal, stderr: info.stderrTail.slice(-500) }, 'codex app-server exited');
    // Every thread must be re-attached by the next app-server; any in-flight
    // turn is lost — settle it so the relay never waits forever.
    for (const s of this.sessions.values()) {
      s.loaded = false;
      if (s.activeTurnId || s.starting) {
        s.activeTurnId = undefined;
        s.starting = false;
        this.dropPendingCards(s, false);
        this.finalizeTurn(s, 'Codex app-server exited unexpectedly');
      }
    }
  }

  async stop(): Promise<void> {
    this.stopping = true;
    for (const s of this.sessions.values()) this.dropPendingCards(s, true);
    const rpc = this.rpc;
    this.rpc = null;
    if (rpc) await rpc.stop();
    this.sessions.clear();
    this.threadToSession.clear();
    this.childThreads.clear();
    logger.info('Codex adapter stopped');
  }

  // ── Sessions ─────────────────────────────────────────

  private newSession(sessionId: string, init: Partial<CodexSession> = {}): CodexSession {
    return {
      sessionId,
      loaded: false,
      mode: DEFAULT_MODE,
      starting: false,
      abortPending: false,
      settledTurns: [],
      turnCommandItems: new Set(),
      turn: new TurnTracker(this, sessionId),
      tools: new Map(),
      pendingPermissions: new Map(),
      pendingQuestions: new Map(),
      queue: [],
      ...init,
    };
  }

  private threadParams(s: CodexSession): Record<string, unknown> {
    return {
      ...(s.cwd && { cwd: s.cwd }),
      ...(s.model && { model: s.model }),
      // Only the approval route is set (so approvals reach the Kraki client).
      // The sandbox is the user's own ~/.codex/config.toml setting — Kraki
      // never widens or narrows it.
      approvalPolicy: 'untrusted',
      developerInstructions: CodexAdapter.DEVELOPER_INSTRUCTIONS,
    };
  }

  private dynamicTools(): unknown[] {
    return [
      {
        type: 'function',
        name: 'ask_user',
        description: 'Ask the human operator a question and BLOCK until they answer. Returns the user\'s answer. Provide `choices` for a multiple-choice question, or omit them for a free-form answer.',
        inputSchema: {
          type: 'object',
          properties: {
            question: { type: 'string', description: 'The question to ask the user.' },
            choices: { type: 'array', items: { type: 'string' }, description: 'Optional multiple-choice options.' },
          },
          required: ['question'],
          additionalProperties: false,
        },
      },
      {
        type: 'function',
        name: 'show_image',
        description: showImageTool.definition.description,
        inputSchema: showImageTool.definition.inputSchema,
      },
      {
        type: 'function',
        name: 'kraki_get_mode',
        description: 'Return the current Kraki permission mode (safe|auto|delegate). Call before irreversible actions.',
        inputSchema: { type: 'object', properties: {}, additionalProperties: false },
      },
    ];
  }

  private bindThread(s: CodexSession, threadId: string): void {
    if (s.threadId && s.threadId !== threadId) this.threadToSession.delete(s.threadId);
    s.threadId = threadId;
    this.threadToSession.set(threadId, s.sessionId);
  }

  async createSession(config: CreateSessionConfig): Promise<{ sessionId: string }> {
    const sessionId = config.sessionId ?? `codex-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const s = this.newSession(sessionId, {
      cwd: config.cwd,
      model: config.model,
      effort: config.reasoningEffort,
    });
    const rpc = await this.ensureServer();
    const res = await rpc.request<{ thread: { id: string }; model?: string }>('thread/start', {
      ...this.threadParams(s),
      dynamicTools: this.dynamicTools(),
    });
    this.bindThread(s, res.thread.id);
    s.loaded = true;
    if (!s.model && res.model) s.model = res.model;
    this.sessions.set(sessionId, s);
    this.persist(s);
    logger.info({ sessionId, threadId: s.threadId, model: s.model }, 'codex session created');
    this.onSessionCreated?.({
      sessionId,
      agent: 'codex',
      model: s.model,
      reasoningEffort: config.reasoningEffort,
    });
    return { sessionId };
  }

  async resumeSession(sessionId: string): Promise<{ sessionId: string }> {
    const existing = this.sessions.get(sessionId);
    if (existing) return { sessionId };
    const meta = this.loadSidecar(sessionId);
    if (!meta?.threadId) throw new Error(`Codex session ${sessionId} has no recorded thread to resume`);
    const s = this.newSession(sessionId, { cwd: meta.cwd, model: meta.model, effort: meta.effort });
    this.bindThread(s, meta.threadId);
    this.sessions.set(sessionId, s);
    logger.info({ sessionId, threadId: meta.threadId }, 'codex session resumed (deferred)');
    return { sessionId };
  }

  async forkSession(sourceSessionId: string, newSessionId: string): Promise<{ sessionId: string }> {
    const src = this.sessions.get(sourceSessionId) ?? (await this.resumeSession(sourceSessionId), this.sessions.get(sourceSessionId)!);
    if (!src.threadId) throw new Error(`Codex session ${sourceSessionId} has no thread to fork`);
    const s = this.newSession(newSessionId, { cwd: src.cwd, model: src.model, effort: src.effort, mode: src.mode });
    const rpc = await this.ensureServer();
    const res = await rpc.request<{ thread: { id: string } }>('thread/fork', {
      threadId: src.threadId,
      ...this.threadParams(s),
      dynamicTools: this.dynamicTools(),
    });
    this.bindThread(s, res.thread.id);
    s.loaded = true;
    this.sessions.set(newSessionId, s);
    this.persist(s);
    this.onSessionCreated?.({ sessionId: newSessionId, agent: 'codex', model: s.model });
    return { sessionId: newSessionId };
  }

  /** Attach the thread to the running app-server (lazy resume). */
  private async ensureLoaded(s: CodexSession): Promise<CodexRpcProcess> {
    const rpc = await this.ensureServer();
    if (s.loaded) return rpc;
    if (!s.threadId) throw new Error(`Codex session ${s.sessionId} has no thread`);
    await rpc.request('thread/resume', {
      threadId: s.threadId,
      excludeTurns: true,
      ...this.threadParams(s),
      dynamicTools: this.dynamicTools(),
    });
    s.loaded = true;
    return rpc;
  }

  private getSession(sessionId: string): CodexSession {
    const s = this.sessions.get(sessionId);
    if (!s) throw new Error(`Session not found: ${sessionId}`);
    return s;
  }

  // ── Turns ────────────────────────────────────────────

  setTurnIdentity(sessionId: string, turnId: string): void {
    const s = this.sessions.get(sessionId);
    if (s) s.turn.relayTurnId = turnId;
  }

  isTurnSettled(sessionId: string): boolean {
    return this.sessions.get(sessionId)?.turn.isSettled === true;
  }

  turnEvent(s: CodexSession): { turnId?: string } {
    return s.turn.event();
  }

  private buildInput(s: CodexSession, text: string, attachments?: Attachment[]): unknown[] {
    const input: unknown[] = [];
    if (s.modeSignal) {
      text = `${modeChangeSignal(s.modeSignal)}\n\n${text}`;
      s.modeSignal = undefined;
    }
    if (text) input.push({ type: 'text', text, text_elements: [] });
    for (const att of attachments ?? []) {
      let bytes: Buffer | null = null;
      let mime = att.mimeType;
      if (att.type === 'image') {
        bytes = Buffer.from(att.data, 'base64');
      } else if (att.type === 'content_ref' && this.opts.attachmentStore) {
        const hit = this.opts.attachmentStore.read(s.sessionId, att.id);
        if (hit) { bytes = hit.bytes; mime = hit.meta.mimeType ?? mime; }
      }
      if (!bytes || !mime.startsWith('image/')) continue;
      const ext = mime === 'image/png' ? 'png' : mime === 'image/webp' ? 'webp' : mime === 'image/gif' ? 'gif' : 'jpg';
      const dir = join(this.storeDir(s.sessionId), 'codex-inputs');
      mkdirSync(dir, { recursive: true });
      const path = join(dir, `${makeId('img')}.${ext}`);
      writeFileSync(path, bytes);
      input.push({ type: 'localImage', path });
    }
    return input;
  }

  async sendMessage(
    sessionId: string,
    text: string,
    attachments?: Attachment[],
    options?: SendMessageOptions,
  ): Promise<void> {
    const s = this.getSession(sessionId);
    const busy = !!s.activeTurnId || s.starting;

    if (busy && options?.delivery === 'steer' && s.activeTurnId) {
      const rpc = await this.ensureLoaded(s);
      try {
        await rpc.request('turn/steer', {
          threadId: s.threadId,
          expectedTurnId: s.activeTurnId,
          input: this.buildInput(s, text, attachments),
        });
        return;
      } catch (err) {
        // The turn ended between our check and the steer — fall through and
        // start a fresh turn with this input.
        logger.debug({ sessionId, err: errMessage(err) }, 'codex steer rejected; starting new turn');
        if (s.activeTurnId || s.starting) {
          s.queue.push({ text, attachments, relayTurnId: s.turn.relayTurnId });
          return;
        }
      }
    } else if (busy) {
      // prompt/follow_up while a turn runs: run it right after the active turn.
      s.queue.push({ text, attachments, relayTurnId: s.turn.relayTurnId });
      return;
    }

    await this.startTurn(s, { text, attachments, relayTurnId: s.turn.relayTurnId });
  }

  private async startTurn(s: CodexSession, input: QueuedInput): Promise<void> {
    s.starting = true;
    s.turnCommandItems = new Set();
    s.turn.beginTurn();
    // A queued input keeps the relay turn it was sent in.
    s.turn.eventTurnId = input.relayTurnId;
    try {
      const rpc = await this.ensureLoaded(s);
      const res = await rpc.request<{ turn: { id: string; status?: string } }>('turn/start', {
        threadId: s.threadId,
        input: this.buildInput(s, input.text, input.attachments),
        ...(s.model && { model: s.model }),
        ...(s.effort && { effort: s.effort }),
        approvalPolicy: 'untrusted',
      });
      // turn/completed may already have landed for an instantly-failing turn.
      if (!s.turn.isSettled && res?.turn?.id) s.activeTurnId = res.turn.id;
    } catch (err) {
      s.starting = false;
      s.abortPending = false;
      s.activeTurnId = undefined;
      s.turn.settleSilently(); // the caller reports the failure
      throw err;
    }
    s.starting = false;
    if (s.abortPending) void this.interruptActive(s);
  }

  async interruptActive(s: CodexSession): Promise<void> {
    if (!s.activeTurnId) return;
    s.abortPending = false;
    if (!this.rpc?.alive) return;
    try {
      await this.rpc.request('turn/interrupt', { threadId: s.threadId, turnId: s.activeTurnId }, 15_000);
    } catch (err) {
      logger.debug({ sessionId: s.sessionId, err: errMessage(err) }, 'codex turn/interrupt failed');
    }
  }

  /** True when a notification belongs to a turn other than the live one. */
  isStale(s: CodexSession, codexTurnId: string): boolean {
    if (!codexTurnId) return false;
    if (s.settledTurns.includes(codexTurnId)) return true;
    return !!s.activeTurnId && s.activeTurnId !== codexTurnId;
  }

  /** Settle the current turn exactly once — its reply (or `error`), then idle —
   *  and run the next queued input. */
  finalizeTurn(s: CodexSession, error?: string): void {
    if (s.turn.isSettled) return;
    s.abortPending = false;
    if (s.activeTurnId) {
      s.settledTurns.push(s.activeTurnId);
      if (s.settledTurns.length > 8) s.settledTurns.shift();
    }
    s.activeTurnId = undefined;
    const ev = this.turnEvent(s);
    const next = s.queue.shift();
    // A queued steer belongs to the relay turn that is ending here: Codex runs
    // it as a new turn, but for the relay it is the same logical turn. Settling
    // that turn now would make the relay drop everything the steer produces.
    const continuesSameTurn = !!next?.relayTurnId && next.relayTurnId === ev.turnId && !s.turn.isAborted;
    s.turn.finish({ error, idle: !continuesSameTurn });
    this.onFlushComplete?.(s.sessionId);
    if (next) {
      this.startTurn(s, next).catch((err) => {
        const turn = next.relayTurnId ? { turnId: next.relayTurnId } : {};
        this.onError?.(s.sessionId, { message: errMessage(err), ...turn });
        // The relay waits for this turn's idle; without it the session would
        // stay "running" forever.
        if (next.relayTurnId) this.onIdle?.(s.sessionId, turn); else this.onIdle?.(s.sessionId);
      });
    }
  }

  /** A tool / question / subagent follows: prose before it was narration. */
  flushNarration(s: CodexSession): void {
    s.turn.toolStarted();
  }

  async abortSession(sessionId: string): Promise<void> {
    const s = this.sessions.get(sessionId);
    if (!s) return;
    s.queue = [];
    s.turn.abort();
    this.dropPendingCards(s, true);
    const commandItems = [...s.turnCommandItems];
    if (s.activeTurnId) await this.interruptActive(s);
    // turn/start still in flight: interrupt as soon as the turn id is known.
    else if (s.starting) s.abortPending = true;
    if (commandItems.length > 0) await this.terminateTurnCommands(s, new Set(commandItems));
    // turn/completed(interrupted) finalizes; if the turn is already gone, do it now.
    if (!s.activeTurnId && !s.starting && !s.turn.isSettled) this.finalizeTurn(s);
  }

  /** Stop means stop: kill commands this turn started that Codex left running.
   *  Background terminals from EARLIER turns (e.g. a dev server the user asked
   *  for) are deliberately left alone. Best effort — never blocks the abort. */
  private async terminateTurnCommands(s: CodexSession, itemIds: Set<string>): Promise<void> {
    const rpc = this.rpc;
    if (!rpc?.alive || !s.threadId) return;
    try {
      const listed = await rpc.request<{ data?: Array<{ itemId?: string; processId?: string }> }>(
        'thread/backgroundTerminals/list', { threadId: s.threadId }, 5_000);
      const targets = (listed?.data ?? []).filter((t) => t.itemId && t.processId && itemIds.has(t.itemId));
      await Promise.all(targets.map((t) => rpc.request('thread/backgroundTerminals/terminate',
        { threadId: s.threadId, processId: t.processId }, 5_000).catch((err) => {
        logger.debug({ sessionId: s.sessionId, err: errMessage(err) }, 'codex terminate command failed');
      })));
      if (targets.length > 0) logger.info({ sessionId: s.sessionId, count: targets.length }, 'codex: terminated commands left running by aborted turn');
    } catch (err) {
      logger.debug({ sessionId: s.sessionId, err: errMessage(err) }, 'codex backgroundTerminals/list failed');
    }
  }

  async killSession(sessionId: string): Promise<void> {
    const s = this.sessions.get(sessionId);
    if (s) {
      await this.abortSession(sessionId);
      if (s.threadId && this.rpc?.alive && s.loaded) {
        this.rpc.request('thread/unsubscribe', { threadId: s.threadId }, 5_000).catch(() => {});
      }
      if (s.threadId) this.threadToSession.delete(s.threadId);
      for (const [tid, c] of this.childThreads) if (c.sessionId === sessionId) this.childThreads.delete(tid);
      this.sessions.delete(sessionId);
    }
    this.onSessionEnded?.(sessionId, { reason: 'killed' });
  }

  async listSessions(): Promise<SessionInfo[]> {
    return [...this.sessions.values()].map((s) => ({
      id: s.sessionId,
      state: s.activeTurnId ? 'active' as const : 'idle' as const,
      model: s.model,
      cwd: s.cwd,
    }));
  }

  async listModels(): Promise<string[]> {
    return this.models.map((m) => m.id);
  }

  async listModelDetails(): Promise<ModelDetail[]> {
    return this.models;
  }

  setSessionMode(sessionId: string, mode: Mode): void {
    const s = this.sessions.get(sessionId);
    if (!s) return;
    if (s.mode !== mode) s.modeSignal = mode;
    s.mode = mode;
  }

  async setSessionModel(sessionId: string, model: string, reasoningEffort?: string): Promise<void> {
    const s = this.getSession(sessionId);
    s.model = model;
    if (reasoningEffort && KRAKI_EFFORTS.includes(reasoningEffort as ReasoningEffort)) {
      s.effort = reasoningEffort as ReasoningEffort;
    }
    // Codex applies turn/start model+effort overrides to the thread for this
    // and subsequent turns, so nothing to send until the next turn.
    this.persist(s);
  }

  getSessionUsage(sessionId: string): SessionUsage | null {
    return this.sessions.get(sessionId)?.usage ?? null;
  }

  setSessionUsage(sessionId: string, usage: SessionUsage): void {
    const s = this.sessions.get(sessionId);
    if (s) s.usage = { ...usage };
  }

  /** Title side-call: an ephemeral thread (never persisted, never mapped to a
   *  Kraki session) on the session's own model at its lowest reasoning effort.
   *  Codex's system prompt is replaced, no Kraki tools are offered, and any
   *  command / file change / tool request it makes is declined because the
   *  thread belongs to no session (see handleServerRequest). */
  async generateTitle(sessionId: string, context: TitleContext): Promise<string | null> {
    const model = context.model ?? this.sessions.get(sessionId)?.model ?? this.loadSidecar(sessionId)?.model;
    const efforts = this.models.find((m) => m.id === model)?.supportedReasoningEfforts;
    const effort = efforts?.[0];
    let threadId: string | undefined;
    try {
      const rpc = await this.ensureServer();
      const res = await rpc.request<{ thread: { id: string } }>('thread/start', {
        cwd: tmpdir(),
        ...(model && { model }),
        ephemeral: true,
        approvalPolicy: 'untrusted',
        sandbox: 'read-only',
        baseInstructions: TITLE_SYSTEM_PROMPT,
      });
      threadId = res.thread.id;
      const id = threadId;
      const result = new Promise<string | null>((resolve) => {
        const timer = setTimeout(() => { this.titleThreads.delete(id); resolve(null); }, 45_000);
        this.titleThreads.set(id, {
          text: '',
          done: (text) => { clearTimeout(timer); this.titleThreads.delete(id); resolve(text); },
        });
      });
      await rpc.request('turn/start', {
        threadId,
        input: [{ type: 'text', text: buildTitlePrompt(context), text_elements: [] }],
        ...(model && { model }),
        ...(effort && { effort }),
      });
      return cleanTitle(await result);
    } catch (err) {
      if (threadId) this.titleThreads.delete(threadId);
      logger.warn({ sessionId, err: errMessage(err) }, 'codex title generation failed');
      return null;
    } finally {
      if (threadId && this.rpc?.alive) {
        this.rpc.request('thread/unsubscribe', { threadId }, 5_000).catch(() => {});
      }
    }
  }

  // ── Permissions & questions (Kraki → Codex) ──────────

  async respondToPermission(sessionId: string, permissionId: string, decision: PermissionDecision, reason?: string): Promise<PermissionResponseResult> {
    const s = this.sessions.get(sessionId);
    if (!s) return 'session_gone';
    const pending = s.pendingPermissions.get(permissionId);
    if (!pending) {
      logger.warn({ sessionId, permissionId }, 'codex respondToPermission: no pending permission');
      return 'not_found';
    }
    s.pendingPermissions.delete(permissionId);
    const allow = decision === 'approve';
    this.answerPermission(pending, allow);
    // Codex's decline carries no text; relay the operator's reason as a steer
    // into the running turn so the model learns why.
    if (!allow && reason && s.activeTurnId && s.threadId && this.rpc?.alive) {
      this.rpc.request('turn/steer', {
        threadId: s.threadId,
        expectedTurnId: s.activeTurnId,
        input: [{ type: 'text', text: `The user denied that request: ${reason}`, text_elements: [] }],
      }).catch((err) => logger.debug({ sessionId, err: errMessage(err) }, 'codex deny-reason steer failed'));
    }

    return 'accepted';
  }

  answerPermission(p: PendingPermission, allow: boolean): void {
    if (!this.rpc) return;
    if (p.kind === 'permissions') {
      const requested = (p.params.permissions ?? {}) as Record<string, unknown>;
      const granted: Record<string, unknown> = {};
      if (allow) {
        if (requested.network) granted.network = requested.network;
        if (requested.fileSystem) granted.fileSystem = requested.fileSystem;
      }
      this.rpc.respond(p.rpcId, { permissions: granted, scope: 'turn' });
    } else {
      this.rpc.respond(p.rpcId, { decision: allow ? 'accept' : 'decline' });
    }
  }

  async respondToQuestion(
    sessionId: string,
    questionId: string,
    answer: QuestionAnswer | string,
    _wasFreeform: boolean,
  ): Promise<QuestionResponseResult> {
    const s = this.sessions.get(sessionId);
    if (!s) return 'session_gone';
    const pending = s.pendingQuestions.get(questionId);
    if (!pending) return 'not_found';
    if (!this.rpc?.alive) return 'session_gone';
    s.pendingQuestions.delete(questionId);

    const value = typeof answer === 'string' ? { text: answer } : answer;
    const images = (value.attachments ?? []).filter((a): a is Extract<Attachment, { type: 'image' }> => a.type === 'image');
    const text = value.text || (images.length ? 'The user answered with image attachment(s).' : '');

    if (pending.source === 'ask_user') {
      this.rpc.respond(pending.rpcId, {
        contentItems: [
          { type: 'inputText', text },
          ...images.map((img) => ({ type: 'inputImage', imageUrl: `data:${img.mimeType};base64,${img.data}` })),
        ],
        success: true,
      });
      return 'accepted';
    }

    // native request_user_input: record, then advance to the next question.
    const qs = pending.questions ?? [];
    const idx = pending.index ?? 0;
    const collected = pending.collected ?? {};
    if (qs[idx]) collected[qs[idx].id] = { answers: [text] };
    if (idx + 1 < qs.length) {
      emitNativeQuestion(this, s, pending.rpcId, qs, idx + 1, collected);
    } else {
      this.rpc.respond(pending.rpcId, { answers: collected });
    }
    return 'accepted';
  }

  /** Resolve every outstanding card for a session (turn ended / abort / stop). */
  dropPendingCards(s: CodexSession, answerServer: boolean): void {
    for (const [id, p] of s.pendingPermissions) {
      if (answerServer && this.rpc?.alive) {
        if (p.kind === 'permissions') this.rpc.respond(p.rpcId, { permissions: {}, scope: 'turn' });
        else this.rpc.respond(p.rpcId, { decision: 'cancel' });
      }
      this.onPermissionAutoResolved?.(s.sessionId, id, 'cancelled');
    }
    s.pendingPermissions.clear();
    for (const [id, q] of s.pendingQuestions) {
      if (answerServer && this.rpc?.alive) {
        if (q.source === 'ask_user') {
          this.rpc.respond(q.rpcId, { contentItems: [{ type: 'inputText', text: 'The user did not answer (turn cancelled).' }], success: false });
        } else {
          this.rpc.respond(q.rpcId, { answers: q.collected ?? {} });
        }
      }
      this.onQuestionAutoResolved?.(s.sessionId, id);
    }
    s.pendingQuestions.clear();
  }

  // ── Codex → Kraki: server requests ───────────────────

  sessionForParams(params: unknown): CodexSession | undefined {
    const threadId = str((params as { threadId?: unknown } | undefined)?.threadId);
    const sid = threadId ? this.threadToSession.get(threadId) : undefined;
    return sid ? this.sessions.get(sid) : undefined;
  }

  /** Owning session for a server request: the session's own thread, or one of
   * the subagent threads it spawned. */
  sessionForRequest(params: unknown): { s: CodexSession; child?: string } | undefined {
    const own = this.sessionForParams(params);
    if (own) return { s: own };
    const threadId = str((params as { threadId?: unknown } | undefined)?.threadId);
    const child = threadId ? this.childThreads.get(threadId) : undefined;
    const s = child ? this.sessions.get(child.sessionId) : undefined;
    return s && child ? { s, child: child.label } : undefined;
  }

  /** Learn subagent threads from the notifications of a thread we own (the
   * session's thread or an already-known subagent thread, for nesting). */
  learnChildThreads(n: RpcNotification, params: Record<string, unknown>): void {
    const threadId = str(params.threadId);
    const owner = threadId
      ? this.threadToSession.get(threadId) ?? this.childThreads.get(threadId)?.sessionId
      : undefined;
    const adopt = (tid: string, label: string, sessionId: string | undefined) => {
      const known = this.childThreads.get(tid);
      if (known && known.label === 'subagent' && label !== 'subagent') known.label = label;
      if (!tid || !sessionId || this.threadToSession.has(tid) || known) return;
      this.childThreads.set(tid, { sessionId, label, tools: new Map() });
      logger.debug({ sessionId, childThreadId: tid, label }, 'codex: subagent thread attached');
    };
    if (n.method === 'thread/started') {
      const thread = params.thread as { id?: unknown; parentThreadId?: unknown } | undefined;
      const parent = str(thread?.parentThreadId);
      const sid = parent ? this.threadToSession.get(parent) ?? this.childThreads.get(parent)?.sessionId : undefined;
      adopt(str(thread?.id), 'subagent', sid);
      return;
    }
    if (!owner || (n.method !== 'item/started' && n.method !== 'item/completed')) return;
    const item = params.item as Record<string, unknown> | undefined;
    if (item?.type === 'subAgentActivity') {
      const path = str(item.agentPath);
      adopt(str(item.agentThreadId), path.split('/').filter(Boolean).pop() || 'subagent', owner);
    } else if (item?.type === 'collabAgentToolCall' && Array.isArray(item.receiverThreadIds)) {
      for (const tid of item.receiverThreadIds) adopt(str(tid), 'subagent', owner);
    }
  }

  // ── Codex → Kraki: notifications ─────────────────────
}
